kiso/aot/arm64.signature:
koukai sentaku EncodeError {
    InvalidRegister;
    InvalidImmediate;
    InvalidCondition;
    MisalignedOffset;
    BranchOutOfRange;
    DuplicateLabel(string);
    UndefinedLabel(string);
    InvalidPatch;
}

kiso/aot/lower.signature:
koukai sentaku LowerError {
    UnsupportedConstant;
    UnsupportedOpcode(int64);
    UnsupportedClosure;
    InvalidFunction;
    InvalidOperand(int64);
    FrameTooLarge;
    EncodeFailure;
    UnsafeType(int64);
    UnsupportedNative(int64);
}

koukai kata LowerResult {
    words: []uint32;
    constants: []uint8;
    patches: []macho.AddressPatch;
    globals: int64;
    error: LowerError?;
}

